{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "We included randomized controlled trials (RCT) and cluster RCTs designed to evaluate the efficacy of opioids prescribed for relief of acute pain in ED-­ discharged patients compared to nonopioid analgesics. All types of pain complaints were considered.",
      "reason": "The review specifies the study design (RCTs and cluster RCTs), the population (ED-discharged patients with acute pain), and the intervention/comparator (opioids vs nonopioid analgesics)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "There were no exclusions based on language or date of publication.",
      "reason": "The review explicitly states the criteria regarding language and date of publication."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review states it excluded studies 'not reporting pain intensities or pain relief (after contacting authors)', but it does not distinguish between studies where outcomes were not measured versus studies where results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "If data were available for at least three studies, results for the main outcome and for adverse events were pooled and meta-­ analyzed. ... Sensitivity analyses were performed for studies with available short-­ term follow-­ up (≤3 days) ... Another sensitivity analysis compared patients treated with codeine versus those treated with other opioids ... Sensitivity analyses were also performed excluding studies with high risk of bias and for studies involving a pediatric population compared to adults. Finally, we repeated the same analyses while excluding studies for which the comparator was only a placebo.",
      "reason": "The review specifies the groups used for synthesis (main outcome, adverse events) and the various sensitivity analyses used to group studies."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "We excluded studies exclusively on patients with substance use disorder or chronic pain, evaluating only opioids given during the ED stay, comparing different opioids head-­ to-­ head, not reporting pain intensities or pain relief (after contacting authors), or available only as abstracts.",
      "reason": "The review provides rationales for its exclusion criteria, such as focusing on acute pain (excluding chronic pain/substance use disorder) and focusing on discharge prescriptions (excluding ED-only administration)."
    }
  ],
  "confidence": 100
}

